<?php
require_once __DIR__.'/includes/bootstrap.php'; require_admin();
$notice='';$error='';$id=(int)($_GET['id']??$_POST['ticket_id']??0);
if(is_post()){verify_csrf();try{$action=$_POST['action']??'reply';$ticketId=(int)$_POST['ticket_id'];$st=$db->prepare('SELECT t.*,u.full_name,u.email FROM support_tickets t JOIN users u ON u.id=t.user_id WHERE t.id=? LIMIT 1');$st->execute([$ticketId]);$ticket=$st->fetch();if(!$ticket)throw new RuntimeException('Ticket not found.');$db->beginTransaction();if($action==='reply'){$msg=trim($_POST['message']??'');if($msg==='')throw new RuntimeException('Reply cannot be empty.');$db->prepare('INSERT INTO support_ticket_messages(ticket_id,sender_admin_id,sender_role,message,is_internal) VALUES(?,?,?,?,0)')->execute([$ticketId,current_user()['id'],'admin',$msg]);$msgId=(int)$db->lastInsertId();$db->prepare("UPDATE support_tickets SET status='answered',assigned_admin_id=? WHERE id=?")->execute([current_user()['id'],$ticketId]);$db->prepare('INSERT INTO support_ticket_events(ticket_id,actor_admin_id,event_type,details) VALUES(?,?,?,?)')->execute([$ticketId,current_user()['id'],'admin_reply','Admin replied to customer']);if(isset($_FILES['attachment'])&&$_FILES['attachment']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['attachment'];if($f['error']!==UPLOAD_ERR_OK||(int)$f['size']>5*1024*1024)throw new RuntimeException('Attachment must upload successfully and be 5 MB or smaller.');$allowed=['pdf'=>'application/pdf','png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','webp'=>'image/webp','txt'=>'text/plain','zip'=>'application/zip'];$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!isset($allowed[$ext])||($mime!==$allowed[$ext]&&!(in_array($ext,['jpg','jpeg'],true)&&$mime==='image/jpeg')))throw new RuntimeException('Unsupported attachment type.');$stored=bin2hex(random_bytes(16)).'.'.$ext;$dest=__DIR__.'/uploads/tickets/'.$stored;if(!move_uploaded_file($f['tmp_name'],$dest))throw new RuntimeException('Could not store attachment.');$db->prepare('INSERT INTO support_ticket_attachments(ticket_id,message_id,admin_id,original_name,stored_name,mime_type,file_size,sha256) VALUES(?,?,?,?,?,?,?,?)')->execute([$ticketId,$msgId,current_user()['id'],substr($f['name'],0,255),$stored,$mime,(int)$f['size'],hash_file('sha256',$dest)]);} $st=$db->prepare('SELECT * FROM users WHERE id=?');$st->execute([$ticket['user_id']]);$user=$st->fetch();if($user){wdh_customer_message($db,$user,'Support replied — '.$ticket['ticket_number'],$msg,'ticket.php?id='.$ticketId,'support_reply',$ticket['order_id'],$ticket['service_id']);}}elseif($action==='internal_note'){$msg=trim($_POST['message']??'');if($msg==='')throw new RuntimeException('Internal note cannot be empty.');$db->prepare('INSERT INTO support_ticket_messages(ticket_id,sender_admin_id,sender_role,message,is_internal) VALUES(?,?,?,?,1)')->execute([$ticketId,current_user()['id'],'admin',$msg]);$db->prepare('INSERT INTO support_ticket_events(ticket_id,actor_admin_id,event_type,details) VALUES(?,?,?,?)')->execute([$ticketId,current_user()['id'],'internal_note','Admin added internal note']);}elseif($action==='status'){$status=$_POST['status']??'open';if(!in_array($status,ticket_statuses(),true))throw new RuntimeException('Invalid status.');$db->prepare('UPDATE support_tickets SET status=?,assigned_admin_id=?,closed_at=CASE WHEN ?="closed" THEN NOW() ELSE NULL END WHERE id=?')->execute([$status,current_user()['id'],$status,$ticketId]);$db->prepare('INSERT INTO support_ticket_events(ticket_id,actor_admin_id,event_type,details) VALUES(?,?,?,?)')->execute([$ticketId,current_user()['id'],'status_change','Status changed to '.$status]);}$db->commit();$notice='Ticket updated.';$id=$ticketId;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$tickets=$db?$db->query('SELECT t.*,u.full_name,u.email FROM support_tickets t JOIN users u ON u.id=t.user_id ORDER BY FIELD(t.priority,"urgent","high","normal","low"), t.updated_at DESC')->fetchAll():[];
$ticket=null;$messages=[];if($id){$st=$db->prepare('SELECT t.*,u.full_name,u.email,s.service_name,s.domain_name FROM support_tickets t JOIN users u ON u.id=t.user_id LEFT JOIN customer_services s ON s.id=t.service_id WHERE t.id=?');$st->execute([$id]);$ticket=$st->fetch();if($ticket){$st=$db->prepare('SELECT m.*,cu.full_name AS client_name,au.full_name AS admin_name FROM support_ticket_messages m LEFT JOIN users cu ON cu.id=m.sender_user_id LEFT JOIN users au ON au.id=m.sender_admin_id WHERE m.ticket_id=? ORDER BY m.id');$st->execute([$id]);$messages=$st->fetchAll();}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Support Desk — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="admin-page"><div class="portal-welcome"><div><span class="eyebrow mint">SUPPORT DESK</span><h1>Customer Support</h1><p>Reply to customers, add internal notes and manage ticket status.</p></div><a class="btn secondary" href="admin.php">Admin Dashboard</a></div><?php if($notice):?><div class="alert success-alert"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="details-grid"><section class="cart-card"><h2>Tickets</h2><?php if(!$tickets):?><p class="muted">No tickets yet.</p><?php else:foreach($tickets as $t):?><a class="detail-line" href="admin-support.php?id=<?=$t['id']?>"><div><strong><?=e($t['ticket_number'])?></strong><span><?=e($t['subject'])?></span><small><?=e($t['full_name'])?> · <?=e($t['email'])?></small></div><span><?=e(ucfirst($t['status']))?> · <?=e(ucfirst($t['priority']))?></span></a><?php endforeach;endif;?></section><?php if($ticket):?><section class="cart-card"><div class="section-head"><span class="eyebrow mint"><?=e(strtoupper($ticket['category']))?></span><h2><?=e($ticket['subject'])?></h2><p><?=e($ticket['ticket_number'])?> · <?=e($ticket['full_name'])?> · <?=e($ticket['email'])?></p></div><div class="ticket-thread"><?php foreach($messages as $m):?><article class="ticket-message <?=!empty($m['is_internal'])?'internal':''?>"><div class="ticket-message-head"><strong><?=e($m['sender_role']==='admin'?($m['is_internal']?'Internal Admin Note':($m['admin_name']?:'WDH Support')):($m['client_name']?:'Customer'))?></strong><span><?=e($m['created_at'])?></span></div><div><?=nl2br(e($m['message']))?></div></article><?php endforeach;?></div><form method="post" enctype="multipart/form-data" style="margin-top:16px"><?=csrf_field()?><input type="hidden" name="ticket_id" value="<?=$ticket['id']?>"><textarea name="message" rows="6" required placeholder="Reply to the customer..."></textarea><label>Attachment (optional, max 5 MB)<input type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.zip"></label><button class="btn primary" name="action" value="reply">Reply & Notify Customer</button></form><form method="post" style="margin-top:10px"><?=csrf_field()?><input type="hidden" name="ticket_id" value="<?=$ticket['id']?>"><textarea name="message" rows="3" placeholder="Admin-only internal note..."></textarea><button class="btn secondary" name="action" value="internal_note">Add Internal Note</button></form><form method="post" style="margin-top:10px;display:flex;gap:10px;align-items:center"><?=csrf_field()?><input type="hidden" name="ticket_id" value="<?=$ticket['id']?>"><select name="status"><?php foreach(ticket_statuses() as $s):?><option value="<?=e($s)?>" <?=$ticket['status']===$s?'selected':''?>><?=e(ucfirst($s))?></option><?php endforeach;?></select><button class="btn secondary" name="action" value="status">Update Status</button></form></section><?php endif;?></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>
